import{_ as a,o as s,c as t,a0 as n}from"./chunks/framework.DQOulFGV.js";const h=JSON.parse('{"title":"Web Development","description":"","frontmatter":{},"headers":[],"relativePath":"web-development.md","filePath":"web-development.md"}'),o={name:"web-development.md"};function p(i,e,r,l,d,c){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="web-development" tabindex="-1">Web Development <a class="header-anchor" href="#web-development" aria-label="Permalink to &quot;Web Development&quot;">​</a></h1><p>Web endpoints in Mamba are first-class language constructs. You do not need to import a framework to spin up a high-performance web server.</p><h2 id="defining-routes" tabindex="-1">Defining Routes <a class="header-anchor" href="#defining-routes" aria-label="Permalink to &quot;Defining Routes&quot;">​</a></h2><p>Use the <code>route</code> keyword to declare HTTP endpoints. All routes automatically inject a <code>req</code> (Request) context object.</p><h3 id="get-requests" tabindex="-1">GET Requests <a class="header-anchor" href="#get-requests" aria-label="Permalink to &quot;GET Requests&quot;">​</a></h3><div class="language-mamba vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mamba</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>route GET &quot;/api/user&quot; {</span></span>
<span class="line"><span>    return json.stringify({</span></span>
<span class="line"><span>        &quot;name&quot;: &quot;Alex&quot;</span></span>
<span class="line"><span>    })</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="post-requests" tabindex="-1">POST Requests <a class="header-anchor" href="#post-requests" aria-label="Permalink to &quot;POST Requests&quot;">​</a></h3><div class="language-mamba vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mamba</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>route POST &quot;/api/users&quot; {</span></span>
<span class="line"><span>    let body = req.body()</span></span>
<span class="line"><span>    let user = json.parse(body)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    return json.stringify({</span></span>
<span class="line"><span>        &quot;status&quot;: &quot;created&quot;,</span></span>
<span class="line"><span>        &quot;user&quot;: user[&quot;name&quot;]</span></span>
<span class="line"><span>    })</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="the-request-object-req" tabindex="-1">The Request Object (<code>req</code>) <a class="header-anchor" href="#the-request-object-req" aria-label="Permalink to &quot;The Request Object (\`req\`)&quot;">​</a></h2><p>Mamba exposes incoming HTTP request data via the native <code>req</code> object.</p><h3 id="query-parameters" tabindex="-1">Query Parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query Parameters&quot;">​</a></h3><p>Access URL query strings (e.g., <code>?search=mamba</code>).</p><div class="language-mamba vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mamba</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let search_term = req.query(&quot;search&quot;)</span></span></code></pre></div><h3 id="headers" tabindex="-1">Headers <a class="header-anchor" href="#headers" aria-label="Permalink to &quot;Headers&quot;">​</a></h3><p>Read HTTP headers.</p><div class="language-mamba vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mamba</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let auth = req.header(&quot;Authorization&quot;)</span></span></code></pre></div><h3 id="body-payload" tabindex="-1">Body Payload <a class="header-anchor" href="#body-payload" aria-label="Permalink to &quot;Body Payload&quot;">​</a></h3><p>Access raw request bodies for POST/PUT endpoints.</p><div class="language-mamba vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mamba</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let raw_body = req.body()</span></span></code></pre></div><h2 id="supported-http-methods" tabindex="-1">Supported HTTP Methods <a class="header-anchor" href="#supported-http-methods" aria-label="Permalink to &quot;Supported HTTP Methods&quot;">​</a></h2><p>Mamba&#39;s native router supports:</p><ul><li><code>GET</code></li><li><code>POST</code></li><li><code>PUT</code></li><li><code>DELETE</code></li><li><code>OPTIONS</code> (Handled automatically with <code>Access-Control-Allow-Origin: *</code> for CORS support)</li></ul>`,22)])])}const b=a(o,[["render",p]]);export{h as __pageData,b as default};
